def find_first_duplicate(arr):
    # Create an empty dictionary to store element counts
    element_counts = {}

    # Iterate through the array and update the element counts
    for num in arr:
        if num not in element_counts:
            element_counts[num] = 1
        else:
            element_counts[num] += 1

    # Iterate through the dictionary to find the first element with a count greater than 1
    for num, count in element_counts.items():
        if count > 1:
            return num

    # If no duplicates are found, return -1
    return -1

